async function updateLiveArticles() {
  console.log('🚀 Starting in-place update for 15 existing articles...');
  
  let successCount = 0;
  let failCount = 0;

  for (const art of articles) {
    try {
      console.log(`⏳ Updating Article ID ${art.id}: "${art.title}"...`);
      const response = await fetch(`https://api.yogkart.com/api/blogs/admin/${art.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'X-Silent': '1'
        },
        body: JSON.stringify(art)
      });

      const resJson = await response.json();
      if (response.ok && resJson.success) {
        console.log(`✅ [SUCCESS] Updated ID ${art.id} -> slug: ${resJson.data?.blog?.slug || art.slug}`);
        successCount++;
      } else {
        console.error(`❌ [FAILED] ID ${art.id}:`, resJson.message || response.statusText);
        failCount++;
      }
    } catch (err) {
      console.error(`❌ [EXCEPTION] ID ${art.id}:`, err.message);
      failCount++;
    }
  }

  console.log(`\n========================================`);
  console.log(`🎉 Update Complete!`);
  console.log(`Total Success: ${successCount}/15`);
  console.log(`Total Failed:  ${failCount}/15`);
  console.log(`========================================`);
}

updateLiveArticles();
